package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", "host=localhost dbname=inventory sslmode=disable")
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	if category == "" {
		category = "all"
	}
	if minPrice == "" {
		minPrice = "0"
	}
	if sortField == "" {
		sortField = "name"
	}

	// Validate sort field against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if !allowedSorts[sortField] {
		sortField = "name"
	}

	// Build query - category uses parameterized approach
	var query string
	var rows *sql.Rows
	var err error

	if category == "all" {
		query = fmt.Sprintf(
			"SELECT id, name, price, stock FROM products WHERE price >= %s AND active = true ORDER BY %s",
			minPrice, sortField,
		)
		rows, err = db.Query(query)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, stock FROM products WHERE category = $1 AND price >= %s AND active = true ORDER BY %s",
			minPrice, sortField,
		)
		rows, err = db.Query(query, category)
	}

	if err != nil {
		http.Error(w, "Query error", http.StatusInternalServerError)
		log.Printf("Query error: %v | query: %s", err, query)
		return
	}
	defer rows.Close()

	var results []string
	for rows.Next() {
		var id int
		var name string
		var price float64
		var stock int
		if err := rows.Scan(&id, &name, &price, &stock); err != nil {
			continue
		}
		results = append(results, fmt.Sprintf("{\"id\":%d,\"name\":\"%s\",\"price\":%.2f,\"stock\":%d}", id, name, price, stock))
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, "[%s]", strings.Join(results, ","))
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Println("Starting inventory service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
